INSERT INTO "activity_artifacts" ("id", "task_id", "run_id", "kind", "path", "content_text", "metadata_json", "created_at") VALUES('50fca4f0-67f3-4a35-88ea-25cce3d3e507','9b6276b6-ba56-4daf-a8ea-b24926041f25',NULL,'app_blueprint','f4e01014-ea95-4a69-b56d-34ceedc767b9.mock-blueprint.json',unistr('{\u000a  "artifactKind": "mock_blueprint",\u000a  "id": "item_9b6276b6-ba56-4daf-a8ea-b24926041f25",\u000a  "name": "todolist 本体",\u000a  "version": 1,\u000a  "summary": "title のみを持つ最小 todo を、一覧中心の 1 ページ構成で作成・確認し、詳細画面から編集・削除できる todolist の中核 Mock。checked で完了を表し、public 前提の軽量な操作感を確認する。",\u000a  "tone": "実用的で軽快。最小構成でも操作の流れが直感的に追える、整理されたUI。",\u000a  "meta": {\u000a    "intent": "title のみの最小 todo を一覧中心で扱い、checked による完了切り替え、詳細画面からの編集・削除、public 前提の操作を確認できる todolist 画面を作る。",\u000a    "selectedSections": [\u000a      {\u000a        "sectionType": "TopMenuSection",\u000a        "selectionReason": "一覧中心の画面で、追加や詳細への導線を上部にまとめてすぐ操作できるようにするため。"\u000a      },\u000a      {\u000a        "sectionType": "DataTableSection",\u000a        "selectionReason": "todo の一覧、完了状態、並び順、基本操作を一画面で確認する中核だから。"\u000a      },\u000a      {\u000a        "sectionType": "BlogPostSection",\u000a        "selectionReason": "選択した todo の詳細内容を読みやすく見せ、詳細画面から編集・削除へつなげるため。"\u000a      },\u000a      {\u000a        "sectionType": "FormSection",\u000a        "selectionReason": "新規作成と詳細編集のどちらにも使える入力導線を用意し、title のみの最小構成を保つため。"\u000a      }\u000a    ]\u000a  },\u000a  "screens": [\u000a    {\u000a      "id": "todo-list",\u000a      "name": "todo 一覧",\u000a      "path": "/todos",\u000a      "purpose": "title のみの todo を一覧で把握し、追加・完了切り替え・詳細確認へすばやく進める 1 ページ完結の中心画面。",\u000a      "layout": {\u000a        "template": "single_column"\u000a      },\u000a      "sections": [\u000a        {\u000a          "id": "todo-list-topmenu",\u000a          "name": "操作バー",\u000a          "componentName": "TopMenuSection",\u000a          "region": "header",\u000a          "selectionReason": "新規追加や詳細確認への主要導線を上部に置き、一覧中心の操作を迷わせないため。",\u000a          "copy": {\u000a            "title": "Todo List",\u000a            "description": "すぐに追加して、すぐに終わらせる。title だけで管理する軽快な todo 画面。",\u000a            "primaryActionLabel": "新規 todo を追加",\u000a            "secondaryActionLabel": "完了済みを表示",\u000a            "emptyStateTitle": "まだ todo はありません",\u000a            "emptyStateDescription": "まずは 1 件追加して、一覧中心の使い心地を確認してください。"\u000a          },\u000a          "dataset": {\u000a            "kind": "navigation",\u000a            "items": [\u000a              {\u000a                "label": "すべて",\u000a                "href": "/todos",\u000a                "active": true\u000a              },\u000a              {\u000a                "label": "未完了",\u000a                "href": "/todos?filter=active",\u000a                "active": false\u000a              },\u000a              {\u000a                "label": "完了済み",\u000a                "href": "/todos?filter=completed",\u000a                "active": false\u000a              }\u000a            ]\u000a          }\u000a        },\u000a        {\u000a          "id": "todo-list-table",\u000a          "name": "todo 一覧表",\u000a          "componentName": "DataTableSection",\u000a          "region": "main",\u000a          "selectionReason": "todo の作成後に最も頻繁に触る一覧・完了切り替え・削除前確認の土台になるため。",\u000a          "copy": {\u000a            "title": "Todo 一覧",\u000a            "description": "checked で完了を表す、最小構成の todo を一覧で管理します。",\u000a            "primaryActionLabel": "新しい todo を作成",\u000a            "secondaryActionLabel": "選択した todo を開く",\u000a            "emptyStateTitle": "表示できる todo がありません",\u000a            "emptyStateDescription": "追加した todo はここに並び、完了状態と操作をすぐ確認できます。"\u000a          },\u000a          "dataset": {\u000a            "kind": "table",\u000a            "columns": [\u000a              {\u000a                "key": "title",\u000a                "label": "Todo"\u000a              },\u000a              {\u000a                "key": "status",\u000a                "label": "状態"\u000a              },\u000a              {\u000a                "key": "updatedAt",\u000a                "label": "更新"\u000a              }\u000a            ],\u000a            "rows": [\u000a              {\u000a                "id": "todo-001",\u000a                "title": "買い物メモをまとめる",\u000a                "status": "未完了",\u000a                "updatedAt": "今日 09:20",\u000a                "checked": false,\u000a                "href": "/todos/todo-001"\u000a              },\u000a              {\u000a                "id": "todo-002",\u000a                "title": "昼休みに請求書を確認する",\u000a                "status": "完了",\u000a                "updatedAt": "今日 08:45",\u000a                "checked": true,\u000a                "href": "/todos/todo-002"\u000a              },\u000a              {\u000a                "id": "todo-003",\u000a                "title": "帰宅前にゴミ出し",\u000a                "status": "未完了",\u000a                "updatedAt": "昨日 18:10",\u000a                "checked": false,\u000a                "href": "/todos/todo-003"\u000a              },\u000a              {\u000a                "id": "todo-004",\u000a                "title": "明日の予定を 3 件に絞る",\u000a                "status": "未完了",\u000a                "updatedAt": "昨日 17:05",\u000a                "checked": false,\u000a                "href": "/todos/todo-004"\u000a              },\u000a              {\u000a                "id": "todo-005",\u000a                "title": "朝のうちに返信を終える",\u000a                "status": "完了",\u000a                "updatedAt": "昨日 09:12",\u000a                "checked": true,\u000a                "href": "/todos/todo-005"\u000a              }\u000a            ]\u000a          }\u000a        }\u000a      ]\u000a    },\u000a    {\u000a      "id": "todo-detail",\u000a      "name": "todo 詳細",\u000a      "path": "/todos/:id",\u000a      "purpose": "選択した todo の内容を確認し、詳細画面から編集・削除できるようにする。",\u000a      "layout": {\u000a        "template": "single_column"\u000a      },\u000a      "sections": [\u000a        {\u000a          "id": "todo-detail-post",\u000a          "name": "todo 詳細本文",\u000a          "componentName": "BlogPostSection",\u000a          "region": "main",\u000a          "selectionReason": "詳細を本文として読みやすく見せ、編集や削除の前に対象 todo を明確にするため。",\u000a          "copy": {\u000a            "title": "Todo 詳細",\u000a            "description": "この todo は public 前提で扱う、最小構成のタスクです。",\u000a            "primaryActionLabel": "編集する",\u000a            "secondaryActionLabel": "削除する",\u000a            "emptyStateTitle": "todo が見つかりません",\u000a            "emptyStateDescription": "一覧に戻って、別の todo を選んでください。"\u000a          },\u000a          "dataset": {\u000a            "kind": "article",\u000a            "title": "買い物メモをまとめる",\u000a            "body": "週末の買い出しに必要なものを、思いついた順ではなく用途ごとに整理してまとめる。title のみの最小管理でも、何をする todo かがひと目で分かるように短く置いておく。完了したら checked を切り替えて、一覧ではすぐ状態が分かるようにする。詳細画面では、内容の確認後にそのまま編集や削除へ進める。\\n\\nTodo 詳細 では、ユーザーが内容を読みながら状況を判断できるように、背景、現在の状態、次に取れる行動を同じ画面で確認できます。\\n\\nこの mock data は実装メモではなく、実際の利用画面に表示される本文として、投稿内容、補足説明、確認したいポイントを含めています。\\n\\n読み手が一覧から詳細へ移動したあとに、本文だけで判断を続けられるよう、具体的な説明文を十分に持たせます。"\u000a          }\u000a        },\u000a        {\u000a          "id": "todo-detail-form",\u000a          "name": "編集フォーム",\u000a          "componentName": "FormSection",\u000a          "region": "main",\u000a          "selectionReason": "詳細画面からそのまま編集できるようにし、title のみの入力に絞った最小の更新導線を示すため。",\u000a          "copy": {\u000a            "title": "Todo を編集",\u000a            "description": "title だけを直して、すぐに一覧へ反映します。",\u000a            "primaryActionLabel": "更新する",\u000a            "secondaryActionLabel": "編集をやめる",\u000a            "emptyStateTitle": "編集対象がありません",\u000a            "emptyStateDescription": "一覧から todo を選び直してください。"\u000a          },\u000a          "dataset": {\u000a            "kind": "form",\u000a            "fields": [\u000a              {\u000a                "name": "title",\u000a                "label": "title",\u000a                "type": "text",\u000a                "placeholder": "todo を入力"\u000a              },\u000a              {\u000a                "name": "checked",\u000a                "label": "完了",\u000a                "type": "checkbox"\u000a              }\u000a            ],\u000a            "submitLabel": "更新する"\u000a          }\u000a        }\u000a      ]\u000a    }\u000a  ],\u000a  "generationNotes": [\u000a    "Questionnaire の回答を優先し、1ページ完結の一覧中心と詳細画面の2画面に絞った。",\u000a    "todo の項目は title のみで最小構成にし、checked で完了を表す前提を dataset と copy に反映した。",\u000a    "編集・削除は詳細画面に寄せ、一覧は確認と遷移の中心として扱った。",\u000a    "public 前提は詳細画面の説明文にのみ反映し、技術スタックや保存方式の説明は画面文言に出さないようにした。"\u000a  ]\u000a}'),'{"messageId":null,"intent":"mock_blueprint","artifactType":"mock_blueprint","title":"todolist 本体","mockBlueprint":{"artifactKind":"mock_blueprint","id":"item_9b6276b6-ba56-4daf-a8ea-b24926041f25","name":"todolist 本体","version":1,"summary":"title のみを持つ最小 todo を、一覧中心の 1 ページ構成で作成・確認し、詳細画面から編集・削除できる todolist の中核 Mock。checked で完了を表し、public 前提の軽量な操作感を確認する。","tone":"実用的で軽快。最小構成でも操作の流れが直感的に追える、整理されたUI。","meta":{"intent":"title のみの最小 todo を一覧中心で扱い、checked による完了切り替え、詳細画面からの編集・削除、public 前提の操作を確認できる todolist 画面を作る。","selectedSections":[{"sectionType":"TopMenuSection","selectionReason":"一覧中心の画面で、追加や詳細への導線を上部にまとめてすぐ操作できるようにするため。"},{"sectionType":"DataTableSection","selectionReason":"todo の一覧、完了状態、並び順、基本操作を一画面で確認する中核だから。"},{"sectionType":"BlogPostSection","selectionReason":"選択した todo の詳細内容を読みやすく見せ、詳細画面から編集・削除へつなげるため。"},{"sectionType":"FormSection","selectionReason":"新規作成と詳細編集のどちらにも使える入力導線を用意し、title のみの最小構成を保つため。"}]},"screens":[{"id":"todo-list","name":"todo 一覧","path":"/todos","purpose":"title のみの todo を一覧で把握し、追加・完了切り替え・詳細確認へすばやく進める 1 ページ完結の中心画面。","layout":{"template":"single_column"},"sections":[{"id":"todo-list-topmenu","name":"操作バー","componentName":"TopMenuSection","region":"header","selectionReason":"新規追加や詳細確認への主要導線を上部に置き、一覧中心の操作を迷わせないため。","copy":{"title":"Todo List","description":"すぐに追加して、すぐに終わらせる。title だけで管理する軽快な todo 画面。","primaryActionLabel":"新規 todo を追加","secondaryA