INSERT INTO "design_questionnaire_sessions" ("id", "created_at", "updated_at", "task_id", "repository_id", "source_blueprint_message_id", "status") VALUES('167bd292-e506-48be-9e07-5309c973ab42',1783419180,1783419249,'9b6276b6-ba56-4daf-a8ea-b24926041f25','984c8844-643e-4596-93a5-703a8d14a1e0',NULL,'review_ready');
INSERT INTO "design_questionnaire_question_sets" ("id", "created_at", "updated_at", "session_id", "sequence", "questionnaire_json", "raw_output", "validation_status") VALUES('e74d220c-b70e-4793-8305-c74c42dc80aa',1783419180,1783419180,'167bd292-e506-48be-9e07-5309c973ab42',1,'{"version":1,"source":{"taskId":"9b6276b6-ba56-4daf-a8ea-b24926041f25","repositoryId":"984c8844-643e-4596-93a5-703a8d14a1e0","sourceKind":"plan_mode_intake","blueprintMessageId":null},"title":"実装前確認フォーム","summary":"実装前に決めたい項目を選択式で確認します。","questionSets":[{"id":"choice-form","title":"実装前確認フォーム","category":"実装前確認","purpose":"実装に入る前に、未決定の仕様判断を選択式で確定します。","questions":[{"id":"q1","topic":"Question 1","question":"この todolist の技術スタックはどの starter template / branch variant を前提にしますか?","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q1-o1","label":"Hono + React/Vite","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o2","label":"Python/FastAPI + React/Vite","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o3","label":"API only","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o4","label":"RAG 系のテンプレート","tradeoff":"選択後に設計判断として整理します。"},{"id":"q1-o5","label":"まだ未確定で、今回はテンプレート選定から始める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-1"},{"id":"q2","topic":"Question 2","question":"保存方式・永続化の前提はどれですか?","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q2-o1","label":"SQLite","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o2","label":"PostgreSQL","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o3","label":"pgvector ありの PostgreSQL","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o4","label":"Turso / libSQL","tradeoff":"選択後に設計判断として整理します。"},{"id":"q2-o5","label":"DB なしで後続決定","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-2"},{"id":"q3","topic":"Question 3","question":"初回の UI はどの構成にしますか?","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q3-o1","label":"1 ページ完結の一覧中心","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o2","label":"一覧と編集を分けた複数画面","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o3","label":"追加フォームを主にした画面","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o4","label":"モバイル向けの簡易 1 画面","tradeoff":"選択後に設計判断として整理します。"},{"id":"q3-o5","label":"まだ未確定で、UI から決める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-3"},{"id":"q4","topic":"Question 4","question":"今回のタスクに持たせる項目はどこまでにしますか?","why":"実装前に仕様判断が必要です。","answerType":"multi_choice","options":[{"id":"q4-o1","label":"title のみで最小構成","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o2","label":"notes を追加する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o3","label":"order を扱う","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o4","label":"tags を追加する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q4-o5","label":"どれも不要","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-4"},{"id":"q5","topic":"Question 5","question":"完了状態はどの表現で扱いますか?","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q5-o1","label":"checked のみで完了を表す","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o2","label":"archived も使う","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o3","label":"checked と archived を両方使い分ける","tradeoff":"選択後に設計判断として整理します。"},{"id":"q5-o4","label":"今回は完了状態を後続決定にする","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-5"},{"id":"q6","topic":"Question 6","question":"編集・削除の導線はどれを主軸にしますか?","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q6-o1","label":"各行に inline 操作を置く","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o2","label":"詳細画面から操作する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o3","label":"モーダル / sheet で操作する","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o4","label":"キーボード操作も含める","tradeoff":"選択後に設計判断として整理します。"},{"id":"q6-o5","label":"まだ未確定で、導線から決める","tradeoff":"選択後に設計判断として整理します。"}],"blocks":["実装前の仕様判断"],"outputSection":"question-6"},{"id":"q7","topic":"Question 7","question":"route / API / data の保護方針はどの面に置きますか?","why":"実装前に仕様判断が必要です。","answerType":"single_choice","options":[{"id":"q7-o1","label":"